using System.Text.Json;
namespace RealmGate.Server;
public enum RuntimeSessionState { SelectingCharacter, Active, Linkdead, LoggedOut, Rejected }
public sealed record RuntimeSessionPolicy(int MaximumCharactersPerAccount,TimeSpan LinkdeadGracePeriod,TimeSpan IdleTimeout,bool AllowSessionTakeover,bool RequireSafeLogout,bool PreventDuplicateCharacterLogin);
public sealed record RuntimeCharacterSlot(string CharacterId,bool Deleted,bool Banned,string? ModuleRestriction);
public sealed record RuntimeAccountSession(string AccountId,string SessionId,string? CharacterId,RuntimeSessionState State,DateTimeOffset ConnectedUtc,DateTimeOffset LastActivityUtc,DateTimeOffset? LinkdeadUntilUtc,long Revision);
public sealed record RuntimeSessionOwnerRequest(string Owner,string Operation,string AccountId,string? CharacterId,string CorrelationId);
public sealed record RuntimeSessionResult(bool Accepted,string Code,RuntimeAccountSession? Session,IReadOnlyList<RuntimeSessionOwnerRequest> OwnerRequests);
public sealed class RuntimeSessionOwnershipService
{
 private readonly RuntimeSessionPolicy _policy; private readonly Dictionary<string,RuntimeAccountSession> _sessions=new(StringComparer.OrdinalIgnoreCase); private readonly Dictionary<string,List<RuntimeCharacterSlot>> _characters=new(StringComparer.OrdinalIgnoreCase);
 public RuntimeSessionOwnershipService(RuntimeSessionPolicy policy){if(policy.MaximumCharactersPerAccount<=0||policy.LinkdeadGracePeriod<TimeSpan.Zero||policy.IdleTimeout<=TimeSpan.Zero)throw new ArgumentException("invalid-session-policy");_policy=policy;}
 public RuntimeSessionResult RegisterAccount(string accountId,IReadOnlyList<RuntimeCharacterSlot> characters){if(string.IsNullOrWhiteSpace(accountId))return Reject("invalid-account");if(characters.Count>_policy.MaximumCharactersPerAccount)return Reject("character-slot-limit");if(characters.Any(x=>string.IsNullOrWhiteSpace(x.CharacterId))||characters.Select(x=>x.CharacterId).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=characters.Count)return Reject("invalid-character-slots");_characters[accountId]=characters.ToList();return new(true,"account-registered",null,Array.Empty<RuntimeSessionOwnerRequest>());}
 public RuntimeSessionResult Connect(string accountId,string sessionId,DateTimeOffset now){if(string.IsNullOrWhiteSpace(accountId)||string.IsNullOrWhiteSpace(sessionId))return Reject("invalid-session");if(!_characters.ContainsKey(accountId))return Reject("unknown-account");if(_sessions.ContainsKey(sessionId))return Reject("duplicate-session-id");var s=new RuntimeAccountSession(accountId,sessionId,null,RuntimeSessionState.SelectingCharacter,now,now,null,1);_sessions[sessionId]=s;return new(true,"connected",s,Array.Empty<RuntimeSessionOwnerRequest>());}
 public RuntimeSessionResult SelectCharacter(string sessionId,string characterId,DateTimeOffset now,string? moduleId=null,bool sessionTakeover=false){if(!_sessions.TryGetValue(sessionId,out var s))return Reject("unknown-session");if(s.State is RuntimeSessionState.LoggedOut or RuntimeSessionState.Rejected)return Reject("invalid-session-state");if(!_characters.TryGetValue(s.AccountId,out var slots))return Reject("unknown-account");var slot=slots.FirstOrDefault(x=>x.CharacterId.Equals(characterId,StringComparison.OrdinalIgnoreCase));if(slot is null)return Reject("character-not-owned");if(slot.Deleted)return Reject("character-deleted");if(slot.Banned)return Reject("character-banned");if(!string.IsNullOrWhiteSpace(slot.ModuleRestriction)&&!slot.ModuleRestriction.Equals(moduleId,StringComparison.OrdinalIgnoreCase))return Reject("module-access-restricted");var existing=_sessions.Values.FirstOrDefault(x=>x.CharacterId!=null&&x.CharacterId.Equals(characterId,StringComparison.OrdinalIgnoreCase)&&x.SessionId!=sessionId&&x.State is RuntimeSessionState.Active or RuntimeSessionState.Linkdead);if(existing is not null&&_policy.PreventDuplicateCharacterLogin){if(!sessionTakeover||!_policy.AllowSessionTakeover)return Reject("duplicate-character-login");_sessions[existing.SessionId]=existing with{State=RuntimeSessionState.LoggedOut,Revision=existing.Revision+1};}
 s=s with{CharacterId=characterId,State=RuntimeSessionState.Active,LastActivityUtc=now,LinkdeadUntilUtc=null,Revision=s.Revision+1};_sessions[sessionId]=s;return new(true,"character-active",s,new[]{Req("Character","load",s),Req("World","enter",s),Req("OfflineMessaging","deliver",s)});}
 public RuntimeSessionResult Touch(string sessionId,DateTimeOffset now){if(!_sessions.TryGetValue(sessionId,out var s))return Reject("unknown-session");if(s.State!=RuntimeSessionState.Active)return Reject("invalid-session-state");s=s with{LastActivityUtc=now,Revision=s.Revision+1};_sessions[sessionId]=s;return new(true,"activity-recorded",s,Array.Empty<RuntimeSessionOwnerRequest>());}
 public RuntimeSessionResult Disconnect(string sessionId,DateTimeOffset now,bool unexpected){if(!_sessions.TryGetValue(sessionId,out var s))return Reject("unknown-session");if(s.State is RuntimeSessionState.LoggedOut or RuntimeSessionState.Rejected)return Reject("invalid-session-state");if(unexpected&&s.CharacterId is not null&&_policy.LinkdeadGracePeriod>TimeSpan.Zero){s=s with{State=RuntimeSessionState.Linkdead,LinkdeadUntilUtc=now+_policy.LinkdeadGracePeriod,Revision=s.Revision+1};_sessions[sessionId]=s;return new(true,"linkdead",s,new[]{Req("Party","mark-offline",s),Req("NpcAi","suspend-followers",s)});}return Logout(sessionId,now,true,true);}
 public RuntimeSessionResult Reconnect(string accountId,string sessionId,string characterId,DateTimeOffset now){var old=_sessions.Values.FirstOrDefault(x=>x.AccountId.Equals(accountId,StringComparison.OrdinalIgnoreCase)&&x.CharacterId!=null&&x.CharacterId.Equals(characterId,StringComparison.OrdinalIgnoreCase)&&x.State==RuntimeSessionState.Linkdead&&x.LinkdeadUntilUtc>=now);if(old is null)return Reject("no-reconnectable-session");_sessions.Remove(old.SessionId);var s=old with{SessionId=sessionId,State=RuntimeSessionState.Active,LastActivityUtc=now,LinkdeadUntilUtc=null,Revision=old.Revision+1};_sessions[sessionId]=s;return new(true,"reconnected",s,new[]{Req("Party","mark-online",s),Req("NpcAi","restore-followers",s),Req("World","restore-presence",s)});}
 public RuntimeSessionResult Logout(string sessionId,DateTimeOffset now,bool safeRoom,bool forced=false){if(!_sessions.TryGetValue(sessionId,out var s))return Reject("unknown-session");if(s.State==RuntimeSessionState.LoggedOut)return Reject("already-logged-out");if(_policy.RequireSafeLogout&&!safeRoom&&!forced)return Reject("safe-room-required");s=s with{State=RuntimeSessionState.LoggedOut,LastActivityUtc=now,LinkdeadUntilUtc=null,Revision=s.Revision+1};_sessions[sessionId]=s;return new(true,forced?"forced-logout":"logged-out",s,new[]{Req("Character","save",s),Req("Party","leave-or-offline",s),Req("NpcAi","cleanup-followers",s),Req("World","exit",s)});}
 public IReadOnlyList<RuntimeSessionResult> ProcessTimeouts(DateTimeOffset now){var list=new List<RuntimeSessionResult>();foreach(var s in _sessions.Values.Where(x=>x.State==RuntimeSessionState.Active&&now-x.LastActivityUtc>=_policy.IdleTimeout).ToArray())list.Add(Logout(s.SessionId,now,true,true));foreach(var s in _sessions.Values.Where(x=>x.State==RuntimeSessionState.Linkdead&&x.LinkdeadUntilUtc<now).ToArray())list.Add(Logout(s.SessionId,now,true,true));return list;}
 public IReadOnlyList<string> ValidateState(){var e=new List<string>();foreach(var s in _sessions.Values){if(string.IsNullOrWhiteSpace(s.AccountId)||string.IsNullOrWhiteSpace(s.SessionId)||s.Revision<=0)e.Add("invalid-session:"+s.SessionId);if(s.State==RuntimeSessionState.Active&&string.IsNullOrWhiteSpace(s.CharacterId))e.Add("active-without-character:"+s.SessionId);}var dup=_sessions.Values.Where(x=>x.State is RuntimeSessionState.Active or RuntimeSessionState.Linkdead&&x.CharacterId!=null).GroupBy(x=>x.CharacterId!,StringComparer.OrdinalIgnoreCase).Where(g=>g.Count()>1);e.AddRange(dup.Select(g=>"duplicate-character:"+g.Key));return e;}
 private static RuntimeSessionOwnerRequest Req(string owner,string op,RuntimeAccountSession s)=>new(owner,op,s.AccountId,s.CharacterId,s.SessionId+":"+s.Revision);
 private static RuntimeSessionResult Reject(string code)=>new(false,code,null,Array.Empty<RuntimeSessionOwnerRequest>());
}
